def specialty_catalogue() -> list[dict[str, Any]]:
    result = []
    for slug, name, description, focus, presentations, themes in _SPECIALTIES:
        result.append({
            "slug": slug, "name": name, "description": description,
            "service_line": name, "focus_areas": list(focus),
            "common_presentations": list(presentations),
            "learning_themes": list(themes), "topic_count": len(themes),
            "topics": [{
                "id": f"{slug}-theme-{index+1}", "title": theme.title(),
                "tagline": f"Explore {theme.lower()} in {name.lower()}.",
                "summary": f"A structured learning theme covering {theme.lower()}, linked to common presentations and source discovery in {name.lower()}.",
                "keywords": list(dict.fromkeys([theme, *presentations[:2], *focus[:2]])),
                "questions": [], "question_count": 0,
                "source_title": "External evidence discovery", "source_url": "",
            } for index, theme in enumerate(themes)],
        })
    return result


