def clinical_event_catalogue() -> list[dict[str, Any]]:
    return [{
        "id": event_id, "title": title, "category": category, "icon": icon,
        "summary": summary, "setting": setting,
        "learning_objectives": list(objectives), "case_signals": list(signals),
        "workspaces": list(workspaces), "active": True,
        "selection_weight": 1, "cooldown_days": 2,
        "review_note": "Scenario theme only; case content must be separately sourced, rights-cleared and clinically reviewed.",
    } for event_id, title, category, icon, summary, setting, objectives, signals, workspaces in _EVENTS]


def catalogue_summary() -> dict[str, Any]:
    specialties = specialty_catalogue()
    events = clinical_event_catalogue()
    return {
        "specialty_count": len(specialties), "clinical_event_count": len(events),
        "specialty_focus_area_count": sum(len(item["focus_areas"]) for item in specialties),
        "learning_theme_count": sum(len(item["learning_themes"]) for item in specialties),
        "event_learning_objective_count": sum(len(item["learning_objectives"]) for item in events),
        "catalogue_version": "6.0.1",
    }
